      if (--depth === 0) { blocks.push(html.slice(open, end)); from = end; }
      continue;
    }
    if (depth === 0) flush(m.index);
    if (RAW.has(tag)) {
      const at = lower.indexOf('</' + tag, end);
      const gt = at < 0 ? -1 : html.indexOf('>', at);
      end = gt < 0 ? html.length : gt + 1;
      re.lastIndex = end;
