    if (tag && tok.endsWith('/>') && lower.startsWith('</' + tag + '>', end)) {
      end += tag.length + 3;
      re.lastIndex = end;
    }
    if (!tag || VOID.has(tag) || RAW.has(tag) || tok.endsWith('/>')) {
      if (depth === 0) { blocks.push(html.slice(m.index, end)); from = end; }
      continue;
    }
    if (depth === 0) open = m.index;
